#!/usr/bin/env python3
"""Regenerate sources.bzl from a CMake/Ninja build of the same Hermes release.

Hermes only ships a CMake build, so the Bazel build reuses the exact source lists CMake links into
libhermesvm (full) and libhermesvmlean, instead of globbing directories.

    cmake -G Ninja -S <hermes-src> -B <build> -DCMAKE_BUILD_TYPE=Release -DHERMESVM_INTERNAL_JAVASCRIPT_NATIVE=OFF
    ninja -C <build> hermesc InternalBytecodeInclude API/hermes/extensions/ExtensionsBytecode.inc
    python3 update_sources.py <hermes-src> <build>

Then copy <build>/lib/InternalJavaScript/InternalBytecode.inc and
<build>/API/hermes/extensions/ExtensionsBytecode.inc into prepared_include/.
"""

import collections
import os
import re
import sys

SHARED = [
    "hermesADT_obj", "hermesFrontEndDefs_obj", "hermesInst_obj", "hermesInstrumentation_obj",
    "hermesInternalBytecode_obj", "hermesPlatformUnicode_obj", "hermesPlatform_obj", "hermesPublic_obj",
    "hermesRegex_obj", "hermesSupport_obj", "hermesVMRuntime_obj", "zip_obj",
]
FULL_ONLY = [
    "hermesAST2JS_obj", "hermesAST_obj", "hermesBackend_obj", "hermesFrontend_obj", "hermesHBCBackend_obj",
    "hermesOptimizer_obj", "hermesParser_obj", "hermesSHBackend_obj", "hermesSema_obj", "hermesSourceMap_obj",
]
LEAN_ONLY = ["hermesHBCBackendLean_obj"]


def main(src_dir, build_dir):
    src_dir = os.path.abspath(src_dir) + "/"
    ninja = open(os.path.join(build_dir, "build.ninja")).read()
    source_of = {m.group(1): m.group(2) for m in re.finditer(r"^build (\S+\.o): \S+ (\S+)", ninja, re.M)}

    def groups(lib):
        line = re.search(r"^build " + re.escape(lib) + r": .*$", ninja, re.M).group(0)
        result = collections.defaultdict(list)
        for obj in (token for token in line.split() if token.endswith(".o")):
            group = re.search(r"CMakeFiles/([^/]+)\.dir/", obj).group(1)
            result[group].append(source_of[obj].replace(src_dir, ""))
        return result

    full = groups("lib/libhermesvm_a.a")
    lean = groups("lib/libhermesvmlean_a.a")

    def collect(names, table):
        return sorted(src for name in names for src in table.get(name, []))

    lists = {
        "LLVH_SRCS": collect(["LLVHSupport_obj"], full),
        "DTOA_SRCS": collect(["dtoa_obj"], full),
        "VM_SRCS": collect(SHARED, full),
        "COMPILER_SRCS": collect(FULL_ONLY, full),
        "LEAN_BACKEND_SRCS": collect(LEAN_ONLY, lean),
        "API_SRCS": collect(["hermesapi_obj"], full),
    }
    known = set(SHARED + FULL_ONLY + LEAN_ONLY + ["LLVHSupport_obj", "dtoa_obj", "hermesapi_obj"])
    unknown = (set(full) | set(lean)) - known
    if unknown:
        sys.exit("Unclassified CMake object groups: {}".format(sorted(unknown)))

    out = ["# Generated by update_sources.py from a CMake build of Hermes. Do not edit.", ""]
    for name, srcs in lists.items():
        out.append("{} = [".format(name))
        out.extend('    "{}",'.format(src) for src in srcs)
        out.extend(["]", ""])
    with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "sources.bzl"), "w") as f:
        f.write("\n".join(out))


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
